use vstd::prelude::*;

verus! {
    fn smallest_num(nums: &Vec<i32>) -> (min: i32)
        requires
            nums.len() > 0, // The array must be non-empty
        ensures
            min <= *nums.iter().max().unwrap() && // min is less than or equal to every element in the array
            nums.contains(&min) // min is equal to at least one element in the array
    {
        let mut min: i32 = nums[0]; // Initialize min to the first element
        let mut idx: usize = 1; // Start from the second element

        while idx < nums.len()
            invariant
                idx <= nums.len(), // idx is within bounds
                min <= *nums.iter().max().unwrap(), // min is less than or equal to the maximum
                nums.contains(&min), // min is contained in the nums
            decreases nums.len() - idx, // Decreases clause for termination
        {
            if nums[idx] < min {
                min = nums[idx]; // Update min if a smaller number is found
            }
            idx += 1; // Move to the next index
        }

        min // Return the found minimum
    }
}

